      "INGRESAR LOS PROYECTOS DE EXTENSIÓN, Y APOYAR A LOS DOCENTES EN EL REGISTRO DE PROYECTOS DE INVESTIGACIÓN EN LA PLATAFORMA HERMES.",
      "PRESENTAR A LA VIE LAS POSIBLES OPORTUNIDADES DE PROYECTOS EN LOS FORMATOS INSTITUCIONALES.",
      "ACOMPAÑAR AL DOCENTE EN PROCESOS DE PLANIFICACIÓN DETALLADA DEL PROYECTO.",
      "GESTIONAR EL CUMPLIMIENTO DE LAS CONDICIONES CONTRACTUALES DE CADA PROYECTO.",
      "REGISTRAR LA LÍNEA BASE DEL PROYECTO EN LAS PLATAFORMAS Y SISTEMAS REQUERIDOS.",
      "PARTICIPAR EN LAS REUNIONES TÉCNICAS Y FINANCIERAS DE CADA PROYECTO.",
      "COORDINAR LOS CANALES DE COMUNICACIÓN ENTRE LOS DIRECTORES DEL PROYECTO, LA MESA OPERATIVA Y ASISTENCIA ADMINISTRATIVA.",
      "COORDINAR CON EL DOCENTE Y/O TÉCNICO LOS REQUERIMIENTOS DE EJECUCIÓN DE LOS PROYECTOS Y EFECTUAR LAS CORRESPONDIENTES MODIFICACIONES PRESUPUESTALES DE ACUERDO A LA PLANIFICACIÓN REALIZADA.",
      "ENTREGAR OPORTUNAMENTE A LA MESA OPERATIVA LA INFORMACIÓN REQUERIDA PARA LAS ORDENES CONTRACTUALES DE LOS PROYECTOS.",
      "ASESORAR A DOCENTES Y CONTRATISTAS EN LOS REQUISITOS Y DOCUMENTOS NECESARIOS PARA LOS PROCESOS CONTRACTUALES.",
      "MONITOREAR LA EJECUCIÓN Y EL VENCIMIENTO DE HITOS E INFORMAR OPORTUNAMENTE AL DIRECTOR PARA GARANTIZAR SU CUMPLIMIENTO Y/O AJUSTE REQUERIDO.",
      "SOLICITAR Y HACER SEGUIMIENTO DE FACTURAS Y DESEMBOLSOS DE ACUERDO A LOS TÉRMINOS CONTRACTUALES DE CADA PROYECTO.",
      "REGISTRAR CONTROL DE CAMBIOS DEL DESARROLLO DE LAS ACTIVIDADES DE LOS PROYECTOS E INFORMAR A.LA VIE AL RESPECTO.",
      "REALIZAR INFORMES PERIÓDICOS DE LOS AVANCES DE CADA PROYECTO CON DESTINO A LOS ENTES DE CONTROL INTERNO Y EXTERNO",
      "ACTUALIZAR EL AVANCE LOS PROYECTOS EN LAS PLATAFORMAS REQUERIDAS PARA LA GESTIÓN DE PROYECTOS.",
      "APOYAR LOS PROCEDIMIENTOS DE LOS PROCESOS PARA QUE SEAN OPORTUNOS, EFECTIVOS Y CUMPLAN CON LA NORMATIVIDAD VIGENTE.",
      "GESTIONAR TRÁMITES CONTRACTUALES CON LAS ENTIDADES CONTRATANTES, PARA LA SUSCRIPCIÓN, EJECUCIÓN Y LIQUIDACIÓN DE PROYECTOS.",
      "GESTIONAR TRÁMITES INTERNOS, PARA LA SUSCRIPCIÓN, EJECUCIÓN Y LIQUIDACIÓN DE PROYECTOS.",
      "MANTENER UN CONTACTO PERMANENTE CON LA MESA OPERATIVA Y HACER SEGUIMIENTO A LAS ACCIONES SOLICITADAS.",
      "RECOPILAR Y SISTEMATIZAR LECCIONES APRENDIDAS DE LOS PROYECTOS PARA LA IMPLEMENTACIÓN DE BUENAS PRÁCTICAS.",
