    "justificacion": "SE REQUIERE PROFESIONAL ESPECIALISTA EN FORMULACIÓN DE PROYECTOS, PARA REALIZAR LA GESTIÓN INTEGRAL DE LOS PROYECTOS EN COMPAÑÍA DE LOS DOCENTES, DURANTE LOS PROCESOS DE PLANIFICACIÓN, EJECUCIÓN, MONITOREO Y CIERRE; DICHA CONTRATACIÓN ES NECESARIA PARA PARA GARANTIZAR LA FORMULACIÓN, DIRECCIÓN Y EVALUACIÓN DE PROYECTOS EN LA FACULTAD DE MINAS, BAJO CRITERIOS DE CO-CREACIÓN, PERTINENCIA, EFICIENCIA, EFICACIA, IMPACTO Y TRASCENDENCIA. LA CONTRATACIÓN CONTRIBUYE A ESTANDARIZAR PROCESOS Y A REALIZAR UNA EFICIENTE GESTIÓN DE LOS PROYECTOS DURANTE SU CICLO DE VIDA Y A SU VEZ PERMITE LA RECOPILACIÓN DE EXPERIENCIAS Y LECCIONES APRENDIDAS PARA GENERACIÓN DE CONOCIMIENTO EN LA FACULTAD Y POR ENDE A LA UNIVERSIDAD. LOS RECURSOS PARA LA CONTRATACIÓN SE ENCUENTRAN APROBADOS Y APROPIADOS EN EL RUBRO Y RECURSO REQUERIDO",
