    "justificacion": "SE REQUIERE PROFESIONAL, PARA APOYAR EL FORTALECIMIENTO DE LA CAPACIDAD DEL SISTEMA DE GESTIÓN DE OPORTUNIDADES Y SOPORTE A LOS PROCESOS ADMINISTRATIVOS DEL CDI, DEL TAL FORMA QUE APORTEN A LOS OBJETIVOS DEL PLAN DE ACCIÓN DE LA DECANATURA DE LA FACULTAD DE MINAS. LA CONTRATACIÓN ES NECESARIA PARA IDENTIFICAR Y DAR A CONOCER NUEVAS OPORTUNIDADES DE PROYECTOS NACIONALES E INTERNACIONALES A LA COMUNIDAD UNIVERSITARIA, DE TAL FORMA QUE PERMITAN INCREMENTAR EL POSICIONAMIENTO DE LA FACULTAD COMO ENTE DINAMIZADOR DEL DESARROLLO LOCAL Y NACIONAL; GARANTIZAR LA FORMULACIÓN, DIRECCIÓN Y EVALUACIÓN DE PROYECTOS DE EDUCACIÓN CONTINUA, BAJO CRITERIOS DE CO-CREACIÓN, PERTINENCIA, EFICIENCIA, EFICACIA, IMPACTO Y TRASCENDENCIA. CONTRIBUYE A LA CLASIFICACIÓN Y COORDINACIÓN CON LOS DOCENTES Y GRUPOS DE INVESTIGACIÓN DE LAS OPORTUNIDADES PARA LA PRESENTACIÓN DE NUEVOS PROYECTOS, CON EL OBJETIVO DE FOMENTAR LA INVESTIGACIÓN APLICADA Y EL APOYO A LAS ENTIDADES EXTERNAS; A ESTANDARIZAR PROCESOS Y A REALIZAR UNA EFICIENTE GESTIÓN DE LOS PROYECTOS DE EDUCACIÓN CONTINUA DURANTE SU CICLO DE VIDA Y A SU VEZ PERMITE LA RECOPILACIÓN DE EXPERIENCIAS Y LECCIONES APRENDIDAS PARA GENERACIÓN DE CONOCIMIENTO EN LA FACULTAD Y POR ENDE A LA UNIVERSIDAD. LOS RECURSOS PARA LA CONTRATACIÓN SE ENCUENTRAN APROBADOS Y APROPIADOS EN EL RUBRO Y RECURSO REQUERIDO",
