    "justificacion": "SE REQUIERE PROFESIONAL PARA FORTALECER EL RELACIONAMIENTO DEL CD+I CON 3 GRUPOS DE INTERÉS PRIORIZADOS: I) MIPYMES Y ESALES; II) EMPRENDIMIENTOS; III) ORGANIZACIONES SOCIALES Y COMUNITARIAS; LA CONTRATACIÓN ES NECESARIA DADO QUE SE DEBE INVOLUCRAR LA FACUTAD DE MINAS CON LAS MIPYMES Y DIVERSOS GRUPOS DE INTERÉS (EMPRESARIOS, EGRESADOS, JUBILADOS, GRUPOS DE INVESTIGACIÓN, EXPERTOS) PARA EL FORTALECIMIENTO DE ESTRATEGIAS Y ACCIONES EN ACUERDOS DE COFINANCIACIÓN. DICHA CONTRATACIÓN CONTRIBUYE COMO ESTRATEGIA PARA AMPLIAR EL PORTAFOLIO DE SERVICIOS DE LA FACULTAD, CUMPLIENDO CON EL OBJETIVOS DE IMPLEMENTAR MECANISMOS DE VINCULACIÓN CON GRUPOS DE INTERÉS AL CENTRO DE DESARROLLO E INNOVACIÓN (CDI). LOS RECURSOS PARA LA CONTRATACIÓN SE ENCUENTRAN APROBADOS Y APROPIADOS EN EL RUBRO Y RECURSO REQUERIDO.",
    "actividades": [
      "COORDINAR LA IMPLEMENTACIÓN DEL CONSULTORIO CD+I, LO QUE INCLUYE: I) REALIZAR LA PLANEACIÓN SEMESTRAL DEL CONSULTORIO; II) CONFORMAR EQUIPOS DE ESTUDIANTES CONSULTORES; III) RECIBIR Y PRIORIZAR LOS CASOS O CONSULTAS RECIBIDOS POR EL CONSULTORIO, Y DISTRIBUIR LA GESTIÓN DE LOS MISMOS A LOS EQUIPOS DEESTUDIANTES CONSULTORES; IV) SER LA PERSONA DE ENLACE E INTERLOCUTOR CON LOS EQUIPOS DE ESTUDIANTESCONSULTORES Y LOS USUARIOS (CONSULTANTES); V) APOYAR EL ACERCAMIENTO INICIAL ENTRE LOS EQUIPO DE ESTUDIANTES CONSULTORES Y LOS USUARIOS DEL CONSULTORIO, FACILITANDO EL ESTABLECIMIENTO DE UN PLAN DE TRABAJO ENTRE ELLOS; VI) SER EL PUNTO DE CONTACTO Y/O CONDUCTO REGULAR DE COMUNICACIÓN PARA LOS ESTUDIANTES CONSULTORES, LOS USUARIOS Y LOS DOCENTES TUTORES, CUANDO ESTOS ASÍ LO REQUIERAN; VII)GESTIONAR LAS INQUIETUDES Y/O SOLICITUDES DE LOS PARTICIPANTES DEL PROCESO DE CONSULTORÍA BÁSICA, DURANTE EL DESARROLLO DEL MISMO (ESTUDIANTES, DOCENTES Y USUARIOS); VIII) DEFINIR Y AGENDAR AL MENOS UNA SESIÓN MENSUAL DE ACOMPAÑAMIENTO CON LOS EQUIPOS DE ESTUDIANTES CONSULTORES, PARA FACILITAR EL DEBIDO DESARROLLO DE LOS DIVERSOS PASOS DE LA RUTA METODOLÓGICA ESTABLECIDA; IX) REVISAR LOS INFORMES Y/O ENTREGABLES ELABORADOS POR LOS EQUIPOS DE ESTUDIANTES CONSULTORES, Y DAR LAS RECOMENDACIONES Y RETROALIMENTACIÓN NECESARIAS, QUE APORTEN AL CUMPLIMIENTO DE LA RUTA METODOLÓGICA ESTABLECIDA; X) ASISTIR Y PARTICIPAR EN LAS REUNIONES A LAS QUE HAYA LUGAR; XI) ELABORAR Y ENVIAR LAS ENCUESTAS DE EVALUACIÓN Y DE PERCEPCIÓN DE SATISFACCIÓN DEL CONSULTORIO CD+I.",
      "DEFINIR, PLANEAR E IMPLEMENTAR ACTIVIDADES QUE FACILITEN EL FORTALECIMIENTO DE LOS Y LAS ESTUDIANTES QUE PARTICIPEN EN LAS ACTIVIDADES DEL CONSULTORIO CD+I, ESPECIALMENTE EN SUS CAPACIDADES PARA LA ADECUADA IMPLEMENTACIÓN DE LA RUTA METODOLÓGICA DEL CONSULTORIO.",
      "PRESENTAR Y/O SOCIALIZAR EL CONSULTORIO CD+I Y SU METODOLOGÍA A GRUPOS DE INTERÉS INTERNOS DE LA SEDE MEDELLÍN DE LA UNAL, TALES COMO: DIRECCIÓN DE INVESTIGACIÓN Y EXTENSIÓN DE SEDE, FACULTADES Y/O VICEDECANATURAS DE LA SEDE, DOCENTES, SEMILLEROS DE INVESTIGACIÓN Y/O GRUPOS ESTUDIANTILES DE LAS FACULTADES DE LA SEDE.",
      "REALIZAR AL MENOS 2 ACTIVIDADES DE ARTICULACIÓN Y/O TRANSFERENCIA DE LA METODOLOGÍA DEL CONSULTORIO CD+I CON DOCENTES Y/O SEMILLEROS DE INVESTIGACIÓN Y GRUPOS ESTUDIANTILES DE OTRAS FACULTADES DE LA SEDE MEDELLÍN DE LA UNAL, PARA POSIBILITANDO EL TRABAJO COLABORATIVO ENTRE ESTOS Y EL CONSULTORIO CD+I O LA IMPLEMENTACIÓN DE LA METODOLOGÍA DEL CONSULTORIO CD+I POR PARTE DE OTRAS FACULTADES DE LA SEDE.",
      "DEFINIR, PLANEAR E IMPLEMENTAR ACTIVIDADES DE DIFUSIÓN, ARTICULACIÓN Y FORTALECIMIENTO DEL CONSULTORIO CD+I, EN COORDINACIÓN CON LA DIRECCIÓN DEL CD+I Y EL ÁREA DE COMUNICACIONES, TALES COMO: PUBLICACIONES, EVENTOS Y CAPACITACIONES, ENTRE OTROS.",
      "GESTIONAR ALIANZAS ENTRE EL CD+I Y DIVERSOS ACTORES DEL SISTEMA EMPRESARIAL Y DE EMPRENDIMIENTO, Y/O CON ORGANIZACIONES SOCIALES Y COMUNITARIAS, Y ACTIVAR Y HACER SEGUIMIENTO AL PROCESO DE FORMALIZACIÓN DE LAS ALIANZAS GESTIONADAS.",
      "DEFINIR, PLANEAR E IMPLEMENTAR ACTIVIDADES, EN COORDINACIÓN CON LA DIRECCIÓN DEL CD+I Y EL ÁREA DE COMUNICACIONES, QUE MOTIVEN LA PARTICIPACIÓN DE ESTUDIANTES, DOCENTES, EGRESADOS, PENSIONADOS Y OTROS INTEGRANTES DE LA COMUNIDAD UNIVERSITARIA, EN LAS ACTIVIDADES DE RELACIONAMIENTO DEL CD+I CON LOS GRUPOS DE INTERÉS PRIORIZADOS.",
      "IDENTIFICAR Y GESTIONAR OPORTUNIDADES PARA EL DESARROLLO DE PROYECTOS CON LOS GRUPOS DE INTERÉS PRIORIZADOS, A TRAVÉS DE LOS CUALES LOS CONOCIMIENTOS Y EXPERIENCIA DE LA FACULTAD DE MINAS Y DEL CD+I FACILITEN EL SOLUCIONAR DIFICULTADES DE DICHOS GRUPOS DE INTERÉS.",
      "CONSOLIDAR Y DOCUMENTAR LA RUTA METODOLÓGICA DEL CONSULTORIO CD+I Y ESTRUCTURAR UNA CAJA DE HERRAMIENTAS ALINEADA CON DICHA RUTA.",
      "ELABORAR Y ENTREGAR REPORTES MENSUALES DE AVANCES E INDICADORES DEL CONSULTORIO CD+I Y EL INFORME SEMESTRAL DE RESULTADOS Y LECCIONES APRENDIDAS."
    ],
